+import { UnauthorizedException } from '@nestjs/common';
+import jwt from 'jsonwebtoken';
+import * as jwksRsa from 'jwks-rsa';
+
+// Mock jwks-rsa before importing the module under test
+jest.mock('jwks-rsa');
+
+import { verifyMicrosoftToken } from './verify-microsoft-token';
+
+describe('verifyMicrosoftToken', () => {
+  const mockClientId = 'test-client-id';
+  const mockGetSigningKey = jest.fn();
+
+  beforeEach(() => {
+    jest.clearAllMocks();
+    (jwksRsa.JwksClient as jest.Mock).mockImplementation(() => ({
+      getSigningKey: mockGetSigningKey,
+    }));
+  });
+
+  it('should return decoded token payload for a valid token', async () => {
+    const secret = 'test-secret';
+    const payload = {
