+      'b2c3d4e5-f6a7-8901-bcde-f12345678901',
+      'c3d4e5f6-a7b8-9012-cdef-123456789012',
+    ],
+  })
+  @IsArray()
+  @IsUUID('4', { each: true })
+  @TransformArray()
+  propertyIds: string[];
+}
+
+export class RfpPropertyVendorStatsResponse {
+  @ApiProperty({
+    description: 'Client Property ID',
