@@ -0,0 +1,40 @@
+import { envValues } from '@app/core';
+import jwt, { JwtPayload } from 'jsonwebtoken';
+
+export interface ChallengeTokenPayload {
+  cognitoUsername: string;
+  email: string;
+  type: 'ms_auth_challenge';
+}
+
+export function createChallengeToken(
+  cognitoUsername: string,
+  email: string,
+): string {
+  const payload: ChallengeTokenPayload = {
+    cognitoUsername,
+    email,
+    type: 'ms_auth_challenge',
+  };
+
+  return jwt.sign(payload, envValues.microsoft.challengeSecret as string, {
+    expiresIn: 120, // 2 minutes
+  });
+}
+
+export function verifyChallengeToken(token: string): ChallengeTokenPayload {
+  const decoded = jwt.verify(
+    token,
+    envValues.microsoft.challengeSecret as string,
+  ) as JwtPayload & ChallengeTokenPayload;
+
+  if (decoded.type !== 'ms_auth_challenge') {
+    throw new Error('Invalid challenge token type');
+  }
+
+  return {
+    cognitoUsername: decoded.cognitoUsername,
+    email: decoded.email,
+    type: decoded.type,
+  };
+}

