Subject: feat(calender): calender enter key fix
Body: 

Changes:
+  /**
+   * Commits the current `inputValue` to the parent.
+   * Shared by blur and Enter — react-datepicker does not reliably forward
+   * `onBlur` while the calendar popover is open.
+   */
+  const commitTypedInput = useCallback(() => {
+    if (!inputValue) {
+      commitSelectedDate(null);
+      prevSelectedKeyRef.current = null;
+      setInputValue('');
+      return;
+    }
+
+    const parsedDate = parseDateInput(inputValue, format);
+    if (!parsedDate) {
+      setDateError('Invalid date');
+      setInputValue(formatDateValue(selectedDate, format));
+      return;
+    }
+
+    if (isDateDisabled(parsedDate)) {
+      setDateError('The choosen date is restricted.');
+      setInputValue(formatDateValue(selectedDate, format));
+      return;
+    }
+
+    prevSelectedKeyRef.current = getDateKey(parsedDate);
+    setSelectedDate(parsedDate);
+    setDateError(null);
+    setInputValue(formatDateValue(parsedDate, format));
+  }, [
+    format,
+    inputValue,
+    isDateDisabled,
+    selectedDate,
+    setDateError,
+    setSelectedDate,
+  ]);
+
